import test from 'node:test';
import assert from 'node:assert/strict';
import {flow} from './opening-flow.mjs';
import {ORIGINS} from '../origin-content.js';
import {convergeOrigin,legacyObjects,originLegacyContext,originPayoffView} from '../origins.js';
import {originPayoff,originRouteReady,activateOriginSupport,validateOriginPayoffs} from '../origin-payoffs.js';
import {findPath} from '../navigation.js';
import {setAssistanceMode,assistanceMode} from '../quest-assistance.js';

function present(origin,destiny){const h=flow(),w=h.w;w.newGame({originId:origin.id});h.finish();Object.assign(w.state.chronicle,{step:4,choices:{repair:0,approach:'diversion',destiny}});convergeOrigin(w);h.finish();w.state.chapter=origin.chapter;let object;for(const scene of w.data.scenes.filter(s=>s.chapter===origin.chapter&&!s.originId&&!s.biome)){w.state.scene=scene.location;object=legacyObjects(w).find(o=>o.legacyId===origin.id);if(object)break;}assert.ok(object,origin.id+' must have an actual inheritance site');return {...h,w,object,record:w.state.chronicle.records.at(-1),original:h};}
test('all fourteen civic outcomes have reachable distinct relationship support, paid only by explicit choice',()=>{for(const origin of ORIGINS)for(const destiny of [0,1]){const h=present(origin,destiny),{w,object,record}=h,profile=originPayoff(record);assert.ok(profile);assert.ok(findPath(w.scene,w.scene.arrive,object.xy,1).length||Math.hypot(w.scene.arrive[0]-object.xy[0],w.scene.arrive[1]-object.xy[1])<=2);assert.deepEqual(originLegacyContext(w),{});h.use(object);assert.ok(h.original.dialog.choices.some(c=>c.label===profile.action));h.choose(1);assert.equal(w.state.chronicle.support.mode,profile.mode);assert.equal(originLegacyContext(w).originSupport.region,origin.chapter);assert.equal(originPayoffView(w.state,w.scene)[0].serviceOpen,true);assert.equal(originRouteReady(w.state,record),false);const saved=w.save();w.restore(saved);h.finish();assert.equal(originLegacyContext(w).originSupport.mode,profile.mode);assert.deepEqual(w.state.chronicle.services,[record.effect]);}});
test('each protagonist’s two historical branches provide different actual preparation modes',()=>{for(const origin of ORIGINS){const modes=origin.effects.map(effect=>originPayoff({effect}).mode);assert.equal(new Set(modes).size,2,origin.id);}});
test('inheritance passages open after the local milestone and route to a real scene without inventing completion',()=>{for(const [hero,destiny]of [[0,1],[5,0],[6,1]]){const origin=ORIGINS[hero],h=present(origin,destiny),{w,record}=h,profile=originPayoff(record);activateOriginSupport(w.state,record);assert.equal(originRouteReady(w.state,record),false);if(origin.chapter===1){w.state.story.weapon=true;w.state.story.firstCore=true;}else w.state.bosses.push(origin.chapter);assert.equal(originRouteReady(w.state,record),true);const choices=JSON.stringify(w.state.storyChoices),bosses=[...w.state.bosses];h.use(legacyObjects(w).find(o=>o.legacyId===origin.id));const at=h.original.dialog.choices.findIndex(c=>c.label===profile.route);assert.ok(at>=0);h.choose(at);assert.equal(w.state.scene,profile.to);assert.deepEqual(w.state.bosses,bosses);assert.equal(JSON.stringify(w.state.storyChoices),choices);assert.equal(w.state.chapter,origin.chapter);}});
test('support is region-bound, one selection at a time, absent from the past, and cannot be forged by a mismatched effect',()=>{const h=present(ORIGINS[0],0),w=h.w,r=h.record;activateOriginSupport(w.state,r);assert.equal(originLegacyContext(w).originSupport.mode,'care');w.state.scene=135;assert.deepEqual(originLegacyContext(w),{});w.state.scene=5;w.state.chronicle.phase='past';assert.deepEqual(originLegacyContext(w),{});w.state.chronicle.phase='present';const bad={...r,effect:'reply-windows'};assert.equal(activateOriginSupport(w.state,bad),false);w.state.chronicle.support.region=24;assert.throws(()=>validateOriginPayoffs(w.state),/support/);});
test('several retained histories share a district without sharing an interaction position',()=>{const h=present(ORIGINS[0],0),w=h.w;w.state.chronicle.records.push({originId:ORIGINS[2].id,hero:2,days:ORIGINS[2].days,repair:0,destiny:1,approach:'diversion',effect:ORIGINS[2].effects[1],cycle:0});w.state.scene=5;const objects=legacyObjects(w);assert.equal(objects.length,2);assert.notDeepEqual(objects[0].xy,objects[1].xy);});
test('old inherited claims stay valid without any new service or support fields',()=>{const h=present(ORIGINS[0],0),w=h.w;h.use(h.object);h.choose(0);const count=w.state.items.tonic;validateOriginPayoffs(w.state);w.restore(w.save());h.finish();h.use(legacyObjects(w).find(o=>o.legacyId===ORIGINS[0].id));h.choose(0);assert.equal(w.state.items.tonic,count);assert.equal(w.state.chronicle.support,undefined);});
test('an explicitly chosen assistance mode survives the origin-to-present handoff',()=>{const h=flow(),w=h.w;w.newGame({originId:ORIGINS[0].id});h.finish();setAssistanceMode(w.state,'full');Object.assign(w.state.chronicle,{step:4,choices:{repair:0,approach:'diversion',destiny:0}});convergeOrigin(w);h.finish();assert.equal(assistanceMode(w.state),'full');});
